65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
77	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
81	
82	    /**
83	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
84	     * line here so audit trails can be captured independently of application logging.
85	     */
86	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        rejectMissingOrBlankFields(ownerFieldsDto);
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        owner.setAddress(normalizeAddress(owner.getAddress()));
138	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
139	        owner.setEmail(normalizeEmail(owner.getEmail()));
140	        validatePostcode(owner.getPostcode(), owner.getCity());
141	        if (owner.getRegistrationDate() == null) {
142	            owner.setRegistrationDate(LocalDate.now());
143	        }
144	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
145	        rejectDailyLimitReached(owner.getRegistrationDate());
146	        rejectCityAtCapacity(owner.getCity());
147	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
148	            assignHousehold(owner);
149	        }
150	        rejectDuplicateIdentity(owner);
151	        owner.setCustomerCode(generateCustomerCode(owner));
152	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
153	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
175	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
176	        this.clinicService.saveOwner(currentOwner);
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Transactional
182	    @Override
183	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        this.clinicService.deleteOwner(owner);
189	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        HttpHeaders headers = new HttpHeaders();
200	        Pet pet = petMapper.toPet(petFieldsDto);
201	        owner.setId(ownerId);
202	        pet.setOwner(owner);
203	        pet.getType().setName(null);
204	        this.clinicService.savePet(pet);
205	        PetDto petDto = petMapper.toPetDto(pet);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
207	            .buildAndExpand(pet.getId()).toUri());
208	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
214	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
215	        if (currentOwner != null) {
216	            Pet currentPet = this.clinicService.findPetById(petId);
217	            if (currentPet != null) {
218	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
219	                currentPet.setName(petFieldsDto.getName());
220	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
221	                this.clinicService.savePet(currentPet);
222	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
231	        HttpHeaders headers = new HttpHeaders();
232	        Visit visit = visitMapper.toVisit(visitFieldsDto);
233	        Pet pet = new Pet();
234	        pet.setId(petId);
235	        visit.setPet(pet);
236	        this.clinicService.saveVisit(visit);
237	        VisitDto visitDto = visitMapper.toVisitDto(visit);
238	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
239	            .buildAndExpand(visit.getId()).toUri());
240	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
241	    }
