243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner != null) {
249	            Pet pet = owner.getPet(petId);
250	            if (pet != null) {
251	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    /**
258	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
259	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
260	     *
261	     * @param fields the submitted owner fields
262	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
263	     *                                        {@code null} or blank, or if address is blank after
264	     *                                        normalization
265	     */
266	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
267	        List<String> missing = new ArrayList<>();
268	        if (isBlank(fields.getFirstName())) {
269	            missing.add("firstName");
270	        }
271	        if (isBlank(fields.getLastName())) {
272	            missing.add("lastName");
273	        }
274	        if (isBlank(normalizeAddress(fields.getAddress()))) {
275	            missing.add("address");
276	        }
277	        if (isBlank(fields.getCity())) {
278	            missing.add("city");
279	        }
280	        if (isBlank(fields.getTelephone())) {
281	            missing.add("telephone");
282	        }
283	        if (!missing.isEmpty()) {
284	            throw new RequiredFieldsMissingException(missing);
285	        }
286	    }
287	
288	    private boolean isBlank(String value) {
289	        return value == null || value.isBlank();
290	    }
291	
292	    /**
293	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
294	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
295	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
296	     */
297	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
298	        "NSW", new int[] {2000, 2099},
299	        "VIC", new int[] {3000, 3099},
300	        "QLD", new int[] {4000, 4099});
301	
302	    /**
303	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
304	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
305	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
306	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
307	     *
308	     * @param postcode the submitted postcode, or {@code null} when omitted
309	     * @param city the owner's city, used to derive the region whose range constrains the postcode
310	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
311	     *                                  city's region
312	     */
313	    private void validatePostcode(String postcode, String city) {
314	        if (postcode == null) {
315	            return;
316	        }
317	        if (!postcode.matches("[0-9]{4}")) {
318	            throw new InvalidPostcodeException(postcode);
319	        }
320	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
321	        if (range == null) {
322	            return;
323	        }
324	        int value = Integer.parseInt(postcode);
325	        if (value < range[0] || value > range[1]) {
326	            throw new InvalidPostcodeException(postcode);
327	        }
328	    }
329	
330	    /**
331	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
332	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
333	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
334	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
335	     * <p>
336	     * Where a per-country rule is defined the national-number length is validated against the country
337	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
338	     * requires exactly 10.
339	     *
340	     * @param telephone the raw telephone value from the request
341	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
342	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
343	     */
344	    private String normalizeTelephone(String telephone) {
345	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
346	        String digits;
347	        if (cleaned.startsWith("+")) {
348	            digits = cleaned.substring(1);
349	        } else {
350	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
351	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
352	            digits = "61" + national;
353	        }
354	        if (!digits.matches("[0-9]{8,15}")) {
355	            throw new InvalidTelephoneException(cleaned);
356	        }
357	        // Validate the national-number length against the country code where a rule is defined.
358	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
359	            throw new InvalidTelephoneException(cleaned);
360	        }
361	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
362	            throw new InvalidTelephoneException(cleaned);
363	        }
364	        return "+" + digits;
365	    }
366	
367	    /**
368	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
369	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
370	     * lower-cased.
371	     *
372	     * @param email the raw email value from the request, or {@code null} if omitted
373	     * @return the lower-cased email, or {@code null} if none was supplied
374	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
375	     */
376	    private String normalizeEmail(String email) {
377	        if (email == null) {
378	            return null;
379	        }
380	        String trimmed = email.strip();
381	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
382	            throw new InvalidEmailException(email);
383	        }
384	        return trimmed.toLowerCase(Locale.ROOT);
385	    }
386	
387	    /**
388	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
389	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
390	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
391	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
392	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
393	     *
394	     * @param address the raw address value from the request (may be {@code null})
395	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
396	     */
397	    private String normalizeAddress(String address) {
398	        if (address == null) {
399	            return "";
400	        }
401	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
402	        if (collapsed.isEmpty()) {
403	            return "";
404	        }
405	        String[] tokens = collapsed.split(" ");
406	        StringBuilder sb = new StringBuilder(collapsed.length());
407	        for (int i = 0; i < tokens.length; i++) {
408	            if (i > 0) {
409	                sb.append(' ');
410	            }
411	            sb.append(expandAddressAbbreviation(tokens[i]));
412	        }
413	        return sb.toString();
414	    }
415	
416	    /**
417	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
418	     * returns the token unchanged when it is not a recognised abbreviation.
419	     *
420	     * @param token an upper-cased whole-word address token
421	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
422	     */
423	    private String expandAddressAbbreviation(String token) {
424	        return switch (token) {
425	            case "ST" -> "STREET";
426	            case "RD" -> "ROAD";
427	            case "AVE" -> "AVENUE";
428	            default -> token;
429	        };
430	    }
431	
432	    /**
433	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
434	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
435	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
436	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
437	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
438	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
439	     * sequence number is assigned.
440	     *
441	     * @param owner the owner being created, with normalized telephone and postcode already set
442	     * @return the assigned customer code
443	     */
444	    private String generateCustomerCode(Owner owner) {
445	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
446	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
447	            .substring(0, 8).toUpperCase(Locale.ROOT);
448	        return region + "-" + hash8;
449	    }
450	
451	    /**
452	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
453	     *
454	     * @param value the value to hash
455	     * @return the 64-character lower-case hex SHA-256 digest
456	     */
457	    private String sha256Hex(String value) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(value.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder sb = new StringBuilder(digest.length * 2);
462	            for (byte b : digest) {
463	                sb.append(String.format("%02x", b));
464	            }
465	            return sb.toString();
466	        } catch (NoSuchAlgorithmException e) {
467	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
468	        }
469	    }
470	
471	    /**
472	     * Counts how many existing owners already share the given first name and last name, compared
473	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
474	     * owner being created.
475	     *
476	     * @param firstName the first name of the owner being created
477	     * @param lastName the last name of the owner being created
478	     * @return the number of existing owners with the same first and last name (case-insensitively)
479	     */
480	    private int countNamesakes(String firstName, String lastName) {
481	        return (int) this.clinicService.findAllOwners().stream()
482	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
483	                && lastName.equalsIgnoreCase(existing.getLastName()))
484	            .count();
485	    }
486	
487	    /**
488	     * The maximum number of owners permitted in a single city. A create request whose city already
489	     * holds this many owners is rejected.
490	     */
491	    private static final int CITY_OWNER_LIMIT = 50;
492	
493	    /**
494	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
495	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
496	     * differing only in the casing of their city share one capacity pool. The count is taken before the
497	     * new owner is persisted, so it excludes the owner being created.
498	     *
499	     * @param city the city of the owner being created
500	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
501	     */
502	    private void rejectCityAtCapacity(String city) {
503	        long existing = this.clinicService.findAllOwners().stream()
504	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
505	            .count();
506	        if (existing >= CITY_OWNER_LIMIT) {
507	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
508	        }
509	    }
510	
511	    /**
512	     * The maximum number of owners permitted to be created in a single day. A create request whose
513	     * registration date already holds this many owners is rejected.
514	     */
515	    private static final int DAILY_OWNER_LIMIT = 100;
516	
517	    /**
518	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
519	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
520	     * persisted, so it excludes the owner being created.
521	     *
522	     * @param registrationDate the registration date of the owner being created
523	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
524	     */
525	    /**
526	     * Adjusts an effective registration date so that it always falls on a business day. When the given
527	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
528	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
529	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
530	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
531	     * business-day-adjusted date.
532	     *
533	     * @param date the effective registration date, supplied or defaulted
534	     * @return the same date when it is a weekday, otherwise the next Monday
535	     */
536	    private LocalDate rollToBusinessDay(LocalDate date) {
537	        DayOfWeek day = date.getDayOfWeek();
538	        if (day == DayOfWeek.SATURDAY) {
539	            return date.plusDays(2);
540	        }
541	        if (day == DayOfWeek.SUNDAY) {
542	            return date.plusDays(1);
543	        }
544	        return date;
545	    }
546	
547	    /**
548	     * The number of owners that must already exist for a given day before a further create is flagged as a
549	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
550	     * the created owner carries {@code bulkSignupWarning = true}.
551	     */
552	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
553	
554	    /**
555	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
556	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
557	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
558	     * the daily create-limit rule's accumulation path.
559	     *
560	     * @param registrationDate the registration date of the owner being created
561	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
562	     */
563	    private boolean isBulkSignupDay(LocalDate registrationDate) {
564	        long existing = this.clinicService.findAllOwners().stream()
565	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
566	            .count();
567	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
568	    }
569	
570	    private void rejectDailyLimitReached(LocalDate registrationDate) {
571	        long existing = this.clinicService.findAllOwners().stream()
572	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
573	            .count();
574	        if (existing >= DAILY_OWNER_LIMIT) {
575	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
576	        }
577	    }
578	
579	    /**
580	     * Rejects a create request whose owner collides with an existing owner on the single derived
581	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
582	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
583	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
584	     * household (same {@code householdId}) with different telephones have different keys and are both
585	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} must already
586	     * have been assigned (when {@code sharesHousehold} was requested) before this check runs, so the key
587	     * compared here is the same one that is later returned.
588	     *
589	     * @param owner the owner being created, with normalized fields and any shared {@code householdId} set
590	     * @throws DuplicateIdentityException if an existing owner has the same identity key
591	     */
592	    private void rejectDuplicateIdentity(Owner owner) {
593	        String key = identityKey(owner);
594	        boolean taken = this.clinicService.findAllOwners().stream()
595	            .anyMatch(existing -> key.equals(identityKey(existing)));
596	        if (taken) {
597	            throw new DuplicateIdentityException(key);
598	        }
599	    }
600	
601	    /**
602	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
603	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
604	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
605	     * Telephone and email are stored already normalized, so the stored values are used directly.
606	     *
607	     * @param owner the owner whose identity key is being derived
608	     * @return the owner's identity key
609	     */
610	    private String identityKey(Owner owner) {
611	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
612	        String email = owner.getEmail() == null ? "" : owner.getEmail();
613	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
614	        return telephone + "|" + email + "|" + householdId;
615	    }
616	
617	    /**
618	     * Assigns the owner being created into a shared household. When at least one existing owner has the
619	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
620	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
621	     * reused when present; otherwise a deterministic id derived from the household's last name and address
622	     * is minted, so independently created members of the same household converge on one value. When no
623	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
624	     *
625	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
626	     */
627	    private void assignHousehold(Owner owner) {
628	        String normalizedLastName = normalizeForComparison(owner.getLastName());
629	        String normalizedAddress = normalizeForComparison(owner.getAddress());
630	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
631	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
632	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
633	            .toList();
634	        if (housemates.isEmpty()) {
635	            return;
636	        }
637	        String householdId = housemates.stream()
638	            .map(Owner::getHouseholdId)
639	            .filter(id -> id != null && !id.isBlank())
640	            .findFirst()
641	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
642	        owner.setHouseholdId(householdId);
643	        for (Owner housemate : housemates) {
644	            if (!householdId.equals(housemate.getHouseholdId())) {
645	                housemate.setHouseholdId(householdId);
646	                this.clinicService.saveOwner(housemate);
647	            }
648	        }
649	    }
650	
651	    /**
652	     * Derives a stable household identifier from the normalized last name and address of a household, as
653	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
654	     * deterministic, so any owner independently joining the same household computes the same identifier.
655	     *
656	     * @param normalizedLastName the household's last name, already normalized for comparison
657	     * @param normalizedAddress the household's address, already normalized for comparison
658	     * @return a stable, shareable household identifier
659	     */
660	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
661	        String key = normalizedLastName + "|" + normalizedAddress;
662	        return sha256Hex(key).substring(0, 16);
663	    }
664	
665	    /**
666	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
667	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
668	     * lower-cased.
669	     *
670	     * @param value the raw value to normalize (may be {@code null})
671	     * @return the normalized value, or an empty string when {@code value} is {@code null}
672	     */
673	    private String normalizeForComparison(String value) {
674	        if (value == null) {
675	            return "";
676	        }
677	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
678	    }
679	}
