46	import org.springframework.web.bind.annotation.ResponseBody;
47	
48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
64	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
65	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
66	
67	    /**
68	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
69	     * class.
70	     *
71	     * @param e     Object referring to the thrown exception.
72	     * @param status HTTP response status.
73	     * @param url URL request.
74	     */
75	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
76	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
77	        problemDetail.setType(URI.create(url.toString()));
78	        problemDetail.setTitle(e.getClass().getSimpleName());
79	        problemDetail.setDetail(detail);
80	        problemDetail.setProperty("timestamp", Instant.now());
81	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
82	        return problemDetail;
83	    }
84	
85	    /**
86	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
87	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
88	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
89	     * would catch it and report an authorization failure as a 500.
90	     *
91	     * @param e The {@link AccessDeniedException} to propagate
92	     * @throws AccessDeniedException always
93	     */
94	    @ExceptionHandler(AccessDeniedException.class)
95	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
96	        throw e;
97	    }
98	
99	    /**
100	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
101	     *
102	     * @param e The {@link Exception} to be handled
103	     * @param request {@link HttpServletRequest} object referring to the current request.
104	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
105	     */
106	    @ExceptionHandler(Exception.class)
107	    @ResponseBody
108	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
109	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
110	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
117	     * method returns a 404 Not Found status if an entity does not exist.
118	     *
119	     * @param e The {@link DataIntegrityViolationException} to be handled
120	     * @param request {@link HttpServletRequest} object referring to the current request.
121	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
122	     */
123	    @ExceptionHandler(DataIntegrityViolationException.class)
124	    @ResponseBody
125	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
126	        logger.warn("Data integrity violation at {} {}: {}",
127	            request.getMethod(),
128	            request.getRequestURI(),
129	            e.getMessage());
130	        logger.debug("Data integrity violation stacktrace", e);
131	        HttpStatus status = HttpStatus.NOT_FOUND;
132	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
133	        return ResponseEntity.status(status).body(detail);
134	    }
135	
136	    /**
137	     * Handles exception thrown by Bean Validation on controller methods parameters
138	     *
139	     * @param e The {@link MethodArgumentNotValidException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
142	     */
143	    @ExceptionHandler(MethodArgumentNotValidException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
146	        HttpStatus status = HttpStatus.BAD_REQUEST;
147	        BindingErrorsResponse errors = new BindingErrorsResponse();
148	        BindingResult bindingResult = e.getBindingResult();
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
150	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
151	            .map(FieldError::getField)
152	            .distinct()
153	            .toList();
154	        detail.setProperty("errors", invalidFields);
155	        if (bindingResult.hasErrors()) {
156	            errors.addAllErrors(bindingResult);
157	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
158	                .map(fieldError -> {
159	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
160	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
161	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
162	                        fieldError.getField(),
163	                        defaultMessage,
164	                        rejectedValue);
165	                    return new ValidationMessageDto(message)
166	                        .putAdditionalProperty("field", fieldError.getField())
167	                        .putAdditionalProperty("rejectedValue", rejectedValue)
168	                        .putAdditionalProperty("defaultMessage", defaultMessage);
169	                })
170	                .toList();
171	            logger.debug("Validation error at {} {}: {}",
172	                request.getMethod(),
173	                request.getRequestURI(),
174	                bindingResult.getFieldErrors());
175	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
176	            return ResponseEntity.status(status).body(detail);
177	        }
178	        return ResponseEntity.status(status).body(detail);
179	    }
180	
181	    /**
182	     * Handles {@link RequiredFieldsMissingException} raised when a create/update request omits or blanks a
183	     * mandatory owner field that Bean Validation cannot reject on its own (e.g. a whitespace-only value that
184	     * still satisfies a minimum-length constraint).
185	     *
186	     * @param e The {@link RequiredFieldsMissingException} to be handled
187	     * @param request {@link HttpServletRequest} object referring to the current request.
188	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
189	     */
190	    @ExceptionHandler(RequiredFieldsMissingException.class)
191	    @ResponseBody
192	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
193	        HttpStatus status = HttpStatus.BAD_REQUEST;
194	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
195	        detail.setProperty("errors", e.getFields());
196	        logger.debug("Missing required fields at {} {}: {}",
197	            request.getMethod(),
198	            request.getRequestURI(),
199	            e.getFields());
200	        return ResponseEntity.status(status).body(detail);
201	    }
202	
203	    /**
204	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number does not
205	     * normalize to exactly ten digits.
206	     *
207	     * @param e The {@link InvalidTelephoneException} to be handled
208	     * @param request {@link HttpServletRequest} object referring to the current request.
209	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
210	     */
211	    @ExceptionHandler(InvalidTelephoneException.class)
212	    @ResponseBody
213	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
214	        HttpStatus status = HttpStatus.BAD_REQUEST;
215	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
216	        detail.setProperty("errors", List.of("telephone"));
217	        logger.debug("Invalid telephone at {} {}: {}",
218	            request.getMethod(),
219	            request.getRequestURI(),
220	            e.getMessage());
221	        return ResponseEntity.status(status).body(detail);
222	    }
223	
224	    /**
225	     * Handles {@link InvalidEmailException} raised when a submitted owner {@code email} is present but is
226	     * not a syntactically valid address.
227	     *
228	     * @param e The {@link InvalidEmailException} to be handled
229	     * @param request {@link HttpServletRequest} object referring to the current request.
230	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
231	     */
232	    @ExceptionHandler(InvalidEmailException.class)
233	    @ResponseBody
234	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
235	        HttpStatus status = HttpStatus.BAD_REQUEST;
236	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
237	        detail.setProperty("errors", List.of("email"));
238	        logger.debug("Invalid email at {} {}: {}",
239	            request.getMethod(),
240	            request.getRequestURI(),
241	            e.getMessage());
242	        return ResponseEntity.status(status).body(detail);
243	    }
244	
245	    /**
246	     * Handles {@link InvalidPostcodeException} raised when a submitted owner {@code postcode} is present
247	     * but is not a 4-digit value, or is out of range for the owner's city region (NSW 2000-2099,
248	     * VIC 3000-3099, QLD 4000-4099).
249	     *
250	     * @param e The {@link InvalidPostcodeException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
253	     */
254	    @ExceptionHandler(InvalidPostcodeException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
257	        HttpStatus status = HttpStatus.BAD_REQUEST;
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
259	        detail.setProperty("errors", List.of("postcode"));
260	        logger.debug("Invalid postcode at {} {}: {}",
261	            request.getMethod(),
262	            request.getRequestURI(),
263	            e.getMessage());
264	        return ResponseEntity.status(status).body(detail);
265	    }
266	
267	    /**
268	     * Handles {@link DuplicateIdentityException} raised when a create request supplies an owner whose
269	     * derived {@code identityKey} (normalized telephone, email or empty, and household id, joined by
270	     * {@code '|'}) exactly equals that of an existing owner. This single key subsumes the former separate
271	     * telephone, email and household duplicate checks.
272	     *
273	     * @param e The {@link DuplicateIdentityException} to be handled
274	     * @param request {@link HttpServletRequest} object referring to the current request.
275	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
276	     */
277	    @ExceptionHandler(DuplicateIdentityException.class)
278	    @ResponseBody
279	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
280	        HttpStatus status = HttpStatus.CONFLICT;
281	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
282	        detail.setProperty("errors", List.of("identityKey"));
283	        logger.debug("Duplicate identity at {} {}: {}",
284	            request.getMethod(),
285	            request.getRequestURI(),
286	            e.getMessage());
287	        return ResponseEntity.status(status).body(detail);
288	    }
289	
290	    /**
291	     * Handles {@link CityOwnerLimitExceededException} raised when a create request supplies an owner
292	     * whose city (compared case-insensitively) already contains the maximum permitted number of owners.
293	     *
294	     * @param e The {@link CityOwnerLimitExceededException} to be handled
295	     * @param request {@link HttpServletRequest} object referring to the current request.
296	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
297	     */
298	    @ExceptionHandler(CityOwnerLimitExceededException.class)
299	    @ResponseBody
300	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
301	        HttpStatus status = HttpStatus.CONFLICT;
302	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
303	        detail.setProperty("errors", List.of("city"));
304	        logger.debug("City at capacity at {} {}: {}",
305	            request.getMethod(),
306	            request.getRequestURI(),
307	            e.getMessage());
308	        return ResponseEntity.status(status).body(detail);
309	    }
310	
311	    /**
312	     * Handles {@link DailyOwnerLimitExceededException} raised when a create request would exceed the
313	     * maximum number of owners permitted to be created in a single day (compared by
314	     * {@code registrationDate}).
315	     *
316	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
317	     * @param request {@link HttpServletRequest} object referring to the current request.
318	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
319	     */
320	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
321	    @ResponseBody
322	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
323	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
324	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
325	        detail.setProperty("errors", List.of("registrationDate"));
326	        logger.debug("Daily owner limit reached at {} {}: {}",
327	            request.getMethod(),
328	            request.getRequestURI(),
329	            e.getMessage());
330	        return ResponseEntity.status(status).body(detail);
331	    }
332	
333	}
