package org.springframework.samples.petclinic.rest.controller;

import java.time.LocalDate;

/**
 * Raised when a create request supplies a {@code registrationDate} that is later than the server date.
 * A registration cannot be dated in the future. Carries the supplied date and the server date so the API
 * can report the rejection back to the client.
 */
public class FutureRegistrationDateException extends RuntimeException {

    private final LocalDate registrationDate;

    private final LocalDate serverDate;

    public FutureRegistrationDateException(LocalDate registrationDate, LocalDate serverDate) {
        super("The supplied registrationDate " + registrationDate + " is later than the server date " + serverDate);
        this.registrationDate = registrationDate;
        this.serverDate = serverDate;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public LocalDate getServerDate() {
        return this.serverDate;
    }
}

